      "choice.hintLong": "1-9, \u03B2\u03AD\u03BB\u03B7 \u03BA\u03B1\u03B9 {enter}, \u03AE \u03BA\u03BB\u03B9\u03BA \u03B3\u03B9\u03B1 \u03B5\u03C0\u03B9\u03BB\u03BF\u03B3\u03AE \u03B4\u03B9\u03B1\u03B4\u03C1\u03BF\u03BC\u03AE\u03C2",
      "choice.hintContinue": "\xB7 0 \u03B3\u03B9\u03B1 \u03B5\u03C0\u03B9\u03C3\u03C4\u03C1\u03BF\u03C6\u03AE",
      "choice.hintAutoPick": "\xB7 {space} \u03B3\u03B9\u03B1 \u03B5\u03C0\u03B9\u03BB\u03BF\u03B3\u03AE \u03C4\u03CE\u03C1\u03B1",
      "choice.autoPick": "\u038C\u03BB\u03B5\u03C2 \u03BF\u03B9 \u03B4\u03B9\u03B1\u03B4\u03C1\u03BF\u03BC\u03AD\u03C2: \u03B5\u03C0\u03B9\u03BB\u03BF\u03B3\u03AE \u03C3\u03B5 {seconds} \u03B4",
      "choice.autoPickBack": "\u03A0\u03AF\u03C3\u03C9 \u03C3\u03C4\u03BF\u03BD \u03C7\u03C1\u03CC\u03BD\u03BF: \u03B7 \u03B4\u03B9\u03B1\u03B4\u03C1\u03BF\u03BC\u03AE \xAB{label}\xBB \u03BF\u03BB\u03BF\u03BA\u03BB\u03B7\u03C1\u03CE\u03B8\u03B7\u03BA\u03B5. \u038C\u03BB\u03B5\u03C2 \u03BF\u03B9 \u03B4\u03B9\u03B1\u03B4\u03C1\u03BF\u03BC\u03AD\u03C2: \u03B5\u03C0\u03B9\u03BB\u03BF\u03B3\u03AE \u03C3\u03B5 {seconds} \u03B4",
      "endcard.allSeen": "\u03A4\u03B1 \u03AD\u03C7\u03B5\u03C4\u03B5 \u03B4\u03B5\u03B9 \u03CC\u03BB\u03B1.",
      "endcard.someUnseen": "\u03A5\u03C0\u03AC\u03C1\u03C7\u03B5\u03B9 \u03B1\u03BA\u03CC\u03BC\u03B7 \u03C0\u03B5\u03C1\u03B9\u03B5\u03C7\u03CC\u03BC\u03B5\u03BD\u03BF \u03C0\u03BF\u03C5 \u03B4\u03B5\u03BD \u03AD\u03C7\u03B5\u03C4\u03B5 \u03B4\u03B5\u03B9.",
